import csv
cols=["row_id","class","population","context","factor","reported_value","proposed_distribution","basis","source","url","notes"]
R=[]
def r(**k): R.append(k)
OM="https://cascadiaresearch.org/files/Oleson-et-al-2007.pdf"; LE="https://repository.library.noaa.gov/view/noaa/24674/noaa_24674_DS1.pdf"
MD="https://www.cetus.ucsd.edu/docs/publications/McDonaldJASA2001.pdf"; NZ="https://www.cetus.ucsd.edu/docs/publications/McDonaldNZ2006.pdf"
S04="https://www.cetus.ucsd.edu/docs/publications/SirovicDSRII2004.pdf"; S15="https://www.cetus.ucsd.edu/docs/publications/SirovicESR2015.pdf"
HE="https://www.frontiersin.org/journals/marine-science/articles/10.3389/fmars.2020.587110/pdf"; ST="https://animalbiotelemetry.biomedcentral.com/track/pdf/10.1186/s40317-015-0058-3"
WO="https://doi.org/10.1371/journal.pone.0264214"; WH="https://epic.awi.de/id/eprint/60068/"; OL14="https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0115678"
B="Blue"
# ---------- BLUE ----------
r(**{"class":B},population="all",context="all",factor="Fraction of animals that call",reported_value="~1/3 of 38 monitored NEP blue whales vocalised (13/38); tags: 22% of deployments, 50% of males vs 5% of females; non-vocal whales often feeding >50 m",proposed_distribution="each animal present is vocal with p = 0.33 (male-biased; song only from males)",basis="literature",source="Oleson et al. 2007 MEPS; Lewis et al. 2018",url=OM)
r(**{"class":B},population="all",context="Song (AB, Z, SEP, NZ, NWP songs)",factor="Callers per encounter",reported_value="singers solitary, not paired while singing; other whales sometimes within a few km; McDonald 2001: 3 A-B callers tracked simultaneously in one encounter",proposed_distribution="1 singer (p 0.7), 2 (0.2), 3 (0.1); extra singers independent, different ranges",basis="literature + assumed weights",source="Oleson 2007 MEPS; McDonald et al. 2001 JASA",url=MD)
r(**{"class":B},population="NE Pacific",context="Song",factor="Calls per dive / call rate",reported_value="3-10 AB units per dive; song call rate 43.3+-4.5 calls/h; A-B 47.8+-3.7 s, B-A 83.0+-25.1 s (tags: A-B 49+-10, B-B 51+-14, B-A 70+-29)",proposed_distribution="units per dive ~ uniform 3-10; phrase intervals from population rows with individual means (below)",basis="literature",source="Oleson 2007 MEPS; Lewis 2018",url=OM)
r(**{"class":B},population="all",context="Song",factor="Silent gaps: surfacing between dives",reported_value="Antarctic long intervals 172+-48 s (n=44); NZ surfacing gaps median 220 s (109-477, n=28), dive ~727 s; NEP male dive intervals 14-17 min with 4-5 breaths; call pauses match surfacings",proposed_distribution="dive (calling) period ~ N(12, 3) min; surfacing silence ~ lognormal median 200 s (range ~100-480 s)",basis="literature",source="Sirovic 2004; McDonald 2006 NZ; McDonald 2001",url=NZ)
r(**{"class":B},population="all",context="Song",factor="Song session length / bouts",reported_value="songs 'for many hours at a time' (hours to days); singers monitored 0.8-8 h; one male 5 h 25 min; NZ encounters 4 h 25 min and ~7 h with gaps >10 min",proposed_distribution="song bout ~ lognormal median 3 h (0.5-12 h); silent spells between bouts ~ lognormal median 20 min (assumed)",basis="literature (bout) + assumed (inter-bout)",source="McDonald 2001; Oleson 2007 MEPS; McDonald 2006 NZ",url=MD)
r(**{"class":B},population="NE Pacific",context="Singular A/B (pairs/groups, feeding, milling)",factor="Callers / rate",reported_value="2-3 whales, always with another blue whale within ~1 km; 3.9+-3.3 calls/h; B-A 983.5+-743.5 s; single A, B or AB pair per dive",proposed_distribution="group 2-3, 1 caller; rate ~ gamma(mean 4, sd 3.3)/h; one call or AB pair per dive",basis="literature",source="Oleson 2007 MEPS",url=OM,notes="one whale switched from singular calls to song after leaving its partner")
r(**{"class":B},population="all",context="D calls (feeding, both sexes)",factor="Callers / rate / clustering",reported_value="1+ whales, others within 1 km; 4.0+-3.7 calls/h; up to 15 D calls per dive; irregular; used as counter-calls among several whales; D-D 835+-1097 s",proposed_distribution="1-4 callers; rate ~ gamma(mean 4, sd 3.7)/h per caller, clustered within dives (up to 15)",basis="literature",source="Oleson 2007 MEPS; McDonald 2001",url=OM)
r(**{"class":B},population="NZ / all",context="Mixed",factor="Call-type switching within an encounter",reported_value="NZ 21 Dec encounter switched several times between song and shorter downswept calls; NEP whale switched singular -> song",proposed_distribution="EQUAL number of encounters per context: song-only, D/feeding-only, song + D (switching), singular AB (NEP only); no prior weighting",basis="design rule (balanced behaviours); switching documented",source="McDonald 2006 NZ; Oleson 2007 MEPS",url=NZ)
r(**{"class":B},population="all",context="all",factor="Individual vs population variability",reported_value="NZ one whale: song repeat 115.2+-0.9 s (n=115) vs population medians 115-133 s; NEP A calls 19-23 pulses (one whale) vs 5-6 (another); 90 Hz component shift differs between individuals",proposed_distribution="per caller: draw individual mean from population distribution; within-caller SD = 0.3 x population SD (assumed)",basis="literature (qualitative) + assumed ratio",source="McDonald 2006 NZ; McDonald 2001",url=MD)
r(**{"class":B},population="all",context="all",factor="Range and received level",reported_value="calls identifiable at ~250 km in deep water (less on shelf); SEP songs SNR 1-40 dB; 3rd harmonic 0-16 dB below fundamental (propagation)",proposed_distribution="range/SNR is NOT a feature: caller range ~ log-uniform 1-200 km sets detectability only -> fraction of each contour detected, number of fragments, missing quiet units (e.g. Z-call B/C) and harmonics (0-16 dB below fundamental), frequency jitter; drifts over the encounter as the caller approaches/departs",basis="literature + assumed mapping",source="Sirovic 2004 via McDonald 2006 NZ; Malige 2020; McDonald 2001",url=S04)
r(**{"class":B},population="Antarctic; NE Pacific",context="Chorus",factor="Chorus (many distant callers)",reported_value="Antarctic: spectral peak of distant Z-calls (28 Hz, 19 Hz) present much of the year (Sirovic 2009 spectra); Weddell Sea Z-calls year-round, peak Jan-Apr (Thomisch 2016). NEP B calls Jun-Jan, peak Sep",proposed_distribution="Antarctic encounters: chorus present p = 0.6 (Feb-Jul) / 0.3 otherwise; NEP p = 0.3 (Aug-Nov) (assumed); chorus = 10-50 callers at SNR -5 to +5 dB, only fragments of loudest units survive",basis="literature (occurrence) + assumed probabilities",source="Sirovic 2009; Thomisch et al. 2016 ESR 30:239",url="https://cormorant.comp.uvic.ca/archives/list/marmam@devlists.uvic.ca/thread/4YCC6FK47KC5C5UUWGA5EEEOZHYC2X27/")
r(**{"class":B},population="all",context="all",factor="Season",reported_value="NEP B calls Jun-Jan (peak Sep), D calls until ~Nov; SEP2 >90% of SEP song detections; Antarctic year-round, peak Jan-Apr",proposed_distribution="season drawn per encounter; sets context weights and chorus probability",basis="literature",source="Sirovic 2015 ESR; Oleson 2007 AB; Buchan 2015 MMS",url=S15)
# ---------- FIN ----------
F="Fin"
r(**{"class":F},population="all",context="all",factor="Context balance",reported_value="song (males), non-song 20 Hz calls, 40 Hz calls (summer feeding)",proposed_distribution="EQUAL number of encounters per context: song, non-song 20 Hz, 40 Hz calls",basis="design rule (balanced behaviours)",source="-",url="")
r(**{"class":F},population="all",context="all",factor="Fraction of animals that call",reported_value="6/18 (33%) of SoCal tag records contained calls; calling whales more often travelling, in groups",proposed_distribution="each animal vocal with p = 0.33",basis="literature",source="Stimpert et al. 2015 Anim Biotelem",url=ST)
r(**{"class":F},population="Central N Pacific",context="Song",factor="Song bout length",reported_value="tracked singers median 2.3 h (minimum); multi-pattern tracks 3.5 h; longest 12.5 h; bouts often longer than tag deployments",proposed_distribution="song bout ~ lognormal median 3 h (0.5-15 h)",basis="literature",source="Helble et al. 2020",url=HE)
r(**{"class":F},population="Central N Pacific",context="Song",factor="Note rate",reported_value="median 131 notes/h (IQR 100-166); 102/h (A-A era) vs 148/h (doublet era)",proposed_distribution="per singer rate ~ normal(131, 25) notes/h, implied by the INIs of the drawn song type",basis="literature",source="Helble 2020",url=HE)
r(**{"class":F},population="Central N Pacific",context="Song",factor="Silent gaps: surfacing",reported_value="1811 gaps: every median 11.5 min (IQR 5.4-16.9), lasting median 116 s (IQR 87-154); one whale every 18.6 min, 121 s",proposed_distribution="singing period between gaps ~ lognormal median 11.5 min (5-17); gap ~ lognormal median 116 s (87-154)",basis="literature",source="Helble 2020",url=HE)
r(**{"class":F},population="all",context="Non-song / tagged animals",factor="Call rate variability between animals",reported_value="per-tag rates ~8, 76, 109, 150 calls/h (derived from Table 1; 1722 calls / 17.9 h); calls during shallow U-dives 15-20 m; silent gaps of 20-120 min within bouts (Watkins 1987, Atlantic)",proposed_distribution="rate ~ lognormal median 80/h (8-150); silences between bouts ~ uniform 20-120 min",basis="literature (Pacific tags) + Atlantic gap values (flagged)",source="Stimpert 2015; Watkins 1987 cited",url=ST)
r(**{"class":F},population="Central N Pacific",context="Song",factor="Simultaneous singers",reported_value="15 of 115 tracks overlapped with another singer in a 20 x 60 km area; singers usually >1 km apart",proposed_distribution="2nd resolvable singer p = 0.15 (Hawaii); higher where chorus is common (see chorus)",basis="literature",source="Helble 2020",url=HE)
r(**{"class":F},population="all",context="Song",factor="Within-encounter consistency",reported_value="within-day IPI MAD 0.3-1.3 s; variants (singlet/doublet/triplet) probably switched by context, not by individual",proposed_distribution="within-encounter IPI SD ~0.5-1 s; song variant may switch within encounter (p 0.2)",basis="literature",source="Oleson 2014; Wood & Sirovic 2022",url=OL14)
r(**{"class":F},population="E North Pacific",context="40 Hz calls (summer, feeding)",factor="Rate / presence",reported_value="detected in up to ~85% of hours/week (SoCal, Bering) in Jun peak; irregular, not song",proposed_distribution="1-3 callers; rate ~ lognormal median 10/h (1-60) (assumed); clustered",basis="presence literature, rate assumed",source="Sirovic 2013",url="https://www.cetus.ucsd.edu/docs/publications/SirovicMB2013.pdf")
r(**{"class":F},population="NE Pacific (SoCal); Southern Ocean",context="Chorus",factor="Chorus prevalence",reported_value="SoCal 20 Hz index >0 on 99.8% of recording days (peak Sep-Dec); Weddell/Atlantic sector: low-frequency chorus continuous Mar-Jun at most sites, HF chorus from ~Mar; individual pulses detectable at only 2 of 10 sites; chorus SNR annual means 1-6 dB",proposed_distribution="chorus present p = 0.8 SoCal (Sep-Dec) / 0.4 otherwise; Southern Ocean p = 0.8 (Mar-Jun) / 0.2 otherwise; Hawaii p = 0.1 (assumed); chorus = many weak 15-30 Hz pulse fragments (+ HF band in south) at SNR 0-6 dB; 20% of Southern Ocean encounters chorus-only",basis="literature (prevalence) + assumed mapping",source="Sirovic 2015 ESR; Wohle et al. 2025",url=WH)
r(**{"class":F},population="WAP",context="Song",factor="Season / presence",reported_value="song in 45% of recordings in July, 30% in September; none in August; peaks Apr-Jun",proposed_distribution="season sets probability of song vs non-song",basis="literature",source="Wood & Sirovic 2022",url=WO)
r(**{"class":F},population="all",context="all",factor="Range and received level",reported_value="detection range ~186 km (Juan Fernandez model); ~250 km open ocean",proposed_distribution="as blue: range sets detectability (contour completeness, fragmentation, missing HF component/harmonics), drifting over the encounter",basis="literature + assumed",source="Buchan 2019; Sirovic 2004",url="https://int-res.com/abstracts/esr/v39/p135-145")
for prefix,cls in (("BMX","Blue"),("FNX","Fin")):
    rows=[x for x in R if x["class"]==cls]
    for i,x in enumerate(rows,1): x["row_id"]=f"{prefix}{i:02d}"
    fn=f"encounter_context_{cls.lower()}.csv"
    with open(fn,"w",newline="",encoding="utf-8") as f:
        w=csv.DictWriter(f,fieldnames=cols); w.writeheader(); [w.writerow({c:x.get(c,"") for c in cols}) for x in rows]
    print(fn,len(rows))
